// Builds visitor materials, prefabs and a preview scene from Visitors.fbx
// (generated by Tools/Blender/build_visitors.py). Safe to re-run; it overwrites its own outputs.
public static class VisitorModelBuilder
{
    const string ModelPath = "Assets/Models/Characters/Visitors.fbx";
    const string MaterialDir = "Assets/Models/Characters/Materials";
    const string PrefabDir = "Assets/Prefabs/Visitors";
    const string ScenePath = "Assets/Scenes/VisitorPreview.unity";

    // Fur variants are swapped on every "Fur" slot of a visitor.
    static readonly string[] FurMaterials = { "Fur_Gray", "Fur_Red", "Fur_GrayDyed", "Paint_Red" };

    // Markings (Omangi's face and cross, button X, lens X, tail stripes) live in this atlas.
    // Textured materials multiply it by their color; white cells keep the plain color.
    const string AtlasPath = "Assets/Models/Characters/Textures/VisitorAtlas.png";

