    const string SheetMaterial = "Sheet";
    const string SheetBumpMaterial = "Sheet_Bump"; // sheet cloth over protruding parts, no hem flutter

    // Partial dye: the natural fur material with whole clumps recolored to the dye color (VisitorFur
    // _DyeCoverage). Named "<dye>_<percent>"; the plain dye material is not a level (paint/bucket only).
    static readonly int[] DyeCoveragePercents = { 15, 30, 60, 90 };

    static readonly (string natural, string dye)[] DyePairs =
    {
        ("Fur_Gray", "Paint_Red"),    // Koonmungchi painting itself red
        ("Fur_Red", "Fur_GrayDyed"),  // Omangi dyeing itself gray
    };

    // Dye levels from sloppiest to heaviest (never a full 100%), as VisitorDisguise expects them.
    static string[] DyeLevels(string dye) =>
        DyeCoveragePercents.Select(p => $"{dye}_{p}").ToArray();

    [MenuItem("Tools/Visitors/Rebuild Prefabs")]
    public static void Build()
    {
        AssetDatabase.Refresh(); // pick up a freshly exported FBX/atlas
        EnsureFolder(MaterialDir);
        EnsureFolder(PrefabDir);
        CreateMaterials();
        ConfigureImporter();

        var model = AssetDatabase.LoadAssetAtPath<GameObject>(ModelPath);
        var koon = SavePrefab(model, "Koonmungchi", "Fur_Gray", "Body", "Koon_");
        var oma = SavePrefab(model, "Omangi", "Fur_Red", "Body", "Oma_");
        // Each visitor disguises as the other: its own fur change plus the other side's look-alike props.
        // The X glasses are worn by both sides, so they are not a sure sign of an impostor.
        AddDisguise(koon, "Fur_Gray", DyeLevels("Paint_Red"), "Fake_HornBand", "Fake_GoatEars", "Fake_XGlasses", "Fake_PaintBucket");
        AddDisguise(oma, "Fur_Red", DyeLevels("Fur_GrayDyed"), "Fake_ConeNose", "Fake_RaccoonTail", "Fake_XGlasses", "Fake_PaintBucket");
        // The paint bucket takes the head slot (the bucket wins over the headbands) and brings the fur paint.
        // The X glasses cover the eyes (no costume sunglasses over them).
        SetDisguiseRules(koon, new[] { "Fake_PaintBucket", "Fake_HornBand", "Fake_GoatEars" }, new[] { "Fake_PaintBucket" },
            new[] { "Fake_PaintBucket" }, new[] { "Fake_XGlasses" });
        SetDisguiseRules(oma, new[] { "Fake_PaintBucket" }, new[] { "Fake_PaintBucket" }, new[] { "Fake_PaintBucket" },
            new[] { "Fake_XGlasses" });
        // Halloween costumes worn by either side (noise, not clues), one per slot; only the bandage cannot be knocked off.
        foreach (var prefab in new[] { koon, oma })
            AddCostumes(prefab, Costumes);
        // The bucket is coated in the same paint as the fur change.
        SetPartMaterial(oma, "Fake_PaintBucket", "PropBucket_Red", "PropBucket_Gray");
        // Only the real raccoon tail wags; the fake one stays stiff (a possible tell).
        AddTailWag(koon, "Koon_Tail");
        // Both can hide under a ghost sheet (hidden until GhostSheet.Wear()).
        // Parts that push the sheet up (props only show when worn). Surface clues (eyes, markings, dye,
        // glasses) are not listed, so the sheet hides them.
        // The pumpkin helmet is the second cover (GhostSheet picks it for some of the sheeted visitors).
        AddGhostSheet(koon, "Ghost_Sheet", "Pumpkin_Helmet", "Koon_Nose", "Koon_Tail", "Fake_HornBand", "Fake_GoatEars", "Fake_PaintBucket",
            "Costume_WitchHat", "Costume_PumpkinBasket", "Costume_BatWings", "Costume_BunnyHeadband", "Costume_Broom", "Costume_Lollipop",
            "Costume_PirateHat", "Costume_Hook");
        AddGhostSheet(oma, "Ghost_Sheet", "Pumpkin_Helmet", "Oma_Horns", "Oma_Ears", "Oma_Tail", "Fake_ConeNose", "Fake_RaccoonTail", "Fake_PaintBucket",
            "Costume_WitchHat", "Costume_PumpkinBasket", "Costume_BatWings", "Costume_BunnyHeadband", "Costume_Broom", "Costume_Lollipop",
            "Costume_PirateHat", "Costume_Hook");
        // Fixed full-costume variants, for the preview scene.
        var koonCostume = SavePrefab(koon, "Koonmungchi_OmaCostume", "Paint_Red",
            "Body", "Koon_", "Fake_HornBand", "Fake_GoatEars");
        var omaCostume = SavePrefab(oma, "Omangi_KoonCostume", "Fur_GrayDyed",
            "Body", "Oma_", "Fake_ConeNose", "Fake_RaccoonTail", "Fake_XGlasses");

        BuildPreviewScene(koon, oma, koonCostume, omaCostume);
        AssetDatabase.SaveAssets();
        Debug.Log("[Visitors] Rebuilt materials, prefabs and preview scene.");
    }

    static void CreateMaterials()
    {
        var atlasImporter = (TextureImporter)AssetImporter.GetAtPath(AtlasPath);
        atlasImporter.mipmapEnabled = false;
        atlasImporter.wrapMode = TextureWrapMode.Clamp;
        atlasImporter.SaveAndReimport();
        var atlas = AssetDatabase.LoadAssetAtPath<Texture2D>(AtlasPath);

        var lit = Shader.Find("Universal Render Pipeline/Lit");
        var furShader = Shader.Find("Fangame/VisitorFur");
        foreach (var (name, color, smoothness, textured, fur) in MaterialDefs)
        {
            var path = $"{MaterialDir}/{name}.mat";
            var mat = AssetDatabase.LoadAssetAtPath<Material>(path);
            if (mat == null)
            {
                mat = new Material(lit);
                AssetDatabase.CreateAsset(mat, path);
            }
            mat.shader = fur > 0f ? furShader : lit;
            mat.SetColor("_BaseColor", color);
            mat.SetTexture("_BaseMap", textured ? atlas : null);
            if (fur > 0f)
            {
                mat.shaderKeywords = new string[0];
                mat.SetFloat("_FurScale", 9f);
                mat.SetFloat("_FurStrength", 1.5f * fur);
                mat.SetFloat("_Crease", 0.4f * fur);
                mat.SetFloat("_Fiber", 0.4f * fur);
                mat.SetFloat("_ColorVariation", 0.1f * fur);
                mat.SetFloat("_RimStrength", 0.8f * fur);
                mat.SetFloat("_DyeCoverage", 0f);
            }
            else
            {
                var highlights = smoothness >= 0.3f;
                mat.SetFloat("_Smoothness", smoothness);
                mat.SetFloat("_EnvironmentReflections", 0f);
                mat.EnableKeyword("_ENVIRONMENTREFLECTIONS_OFF");
                mat.SetFloat("_SpecularHighlights", highlights ? 1f : 0f);
                if (highlights)
                    mat.DisableKeyword("_SPECULARHIGHLIGHTS_OFF");
                else
                    mat.EnableKeyword("_SPECULARHIGHLIGHTS_OFF");
            }
            EditorUtility.SetDirty(mat);
        }

        foreach (var (natural, dye) in DyePairs)
        {
            var naturalMat = AssetDatabase.LoadAssetAtPath<Material>($"{MaterialDir}/{natural}.mat");
            var dyeColor = AssetDatabase.LoadAssetAtPath<Material>($"{MaterialDir}/{dye}.mat").GetColor("_BaseColor");
            foreach (var percent in DyeCoveragePercents)
            {
                var path = $"{MaterialDir}/{dye}_{percent}.mat";
                var mat = AssetDatabase.LoadAssetAtPath<Material>(path);
                if (mat == null)
                {
                    mat = new Material(naturalMat);
                    AssetDatabase.CreateAsset(mat, path);
                }
                mat.shader = naturalMat.shader;
                mat.CopyPropertiesFromMaterial(naturalMat);
                mat.SetColor("_DyeColor", dyeColor);
                mat.SetFloat("_DyeCoverage", percent / 100f);
                EditorUtility.SetDirty(mat);
            }
        }

        // Golden bikini: metallic gold that reflects the environment, with a faint glow so it never goes dark.
        var goldMetal = AssetDatabase.LoadAssetAtPath<Material>($"{MaterialDir}/CostumeGoldMetal.mat");
        goldMetal.SetFloat("_Metallic", 0.9f);
        goldMetal.SetFloat("_EnvironmentReflections", 1f);
        goldMetal.DisableKeyword("_ENVIRONMENTREFLECTIONS_OFF");
        goldMetal.SetFloat("_SpecularHighlights", 1f);
        goldMetal.DisableKeyword("_SPECULARHIGHLIGHTS_OFF");
        goldMetal.EnableKeyword("_EMISSION");
        goldMetal.SetColor("_EmissionColor", new Color(0.95f, 0.75f, 0.15f) * 0.18f);
        goldMetal.globalIlluminationFlags = MaterialGlobalIlluminationFlags.None;
        EditorUtility.SetDirty(goldMetal);

        // The hook's metal and the sunglasses' lenses reflect the night yard (EnvironmentReflection) too. Lenses keep
        // their color and are mirror-smooth; the hook is silver with a faint glow.
        SetReflective("CostumeHookMetal", 0.8f, 0.85f, 0.1f);
        SetReflective("CostumeLensAmber", 0.6f, 0.9f, 0f);
        SetReflective("CostumeAlienLens", 0.6f, 0.9f, 0f);

        // Frills (maid dress): the ghost sheet's cloth shader with its drape folds as ridges and grooves, no flutter, no eyes.
        var frillMat = AssetDatabase.LoadAssetAtPath<Material>($"{MaterialDir}/CostumeFrill.mat");
        frillMat.shader = Shader.Find("Fangame/VisitorSheet");
        frillMat.SetColor("_BaseColor", new Color(0.95f, 0.95f, 0.93f));
        frillMat.SetFloat("_FlutterAmount", 0f);
        frillMat.SetFloat("_EyeSize", 0f);
        frillMat.SetFloat("_FoldCount", 24f);
        frillMat.SetFloat("_FoldDepth", 0.2f);
        frillMat.SetFloat("_FoldShade", 0.22f);
        frillMat.SetFloat("_FoldTop", 3f);   // the folds are at full depth over the whole band
        frillMat.SetFloat("_FoldFull", 2.9f);
        EditorUtility.SetDirty(frillMat);

        // Ghost sheet: its own fluttering cloth shader.
        var sheetPath = $"{MaterialDir}/{SheetMaterial}.mat";
        var sheetMat = AssetDatabase.LoadAssetAtPath<Material>(sheetPath);
        if (sheetMat == null)
        {
            sheetMat = new Material(Shader.Find("Fangame/VisitorSheet"));
            AssetDatabase.CreateAsset(sheetMat, sheetPath);
        }
        sheetMat.shader = Shader.Find("Fangame/VisitorSheet");
        sheetMat.SetColor("_BaseColor", new Color(0.9f, 0.9f, 0.88f));
        EditorUtility.SetDirty(sheetMat);

        var bumpPath = $"{MaterialDir}/{SheetBumpMaterial}.mat";
        var bumpMat = AssetDatabase.LoadAssetAtPath<Material>(bumpPath);
        if (bumpMat == null)
        {
            bumpMat = new Material(sheetMat);
            AssetDatabase.CreateAsset(bumpMat, bumpPath);
        }
        bumpMat.shader = sheetMat.shader;
        bumpMat.CopyPropertiesFromMaterial(sheetMat);
        bumpMat.SetFloat("_FlutterAmount", 0f);
        bumpMat.SetFloat("_EyeSize", 0f); // eyes belong on the sheet only, not on the bumps
        bumpMat.SetFloat("_FoldDepth", 0f); // so do the drape folds
        EditorUtility.SetDirty(bumpMat);
        AssetDatabase.SaveAssets();
    }

    static void ConfigureImporter()
    {
        var importer = (ModelImporter)AssetImporter.GetAtPath(ModelPath);
        importer.animationType = ModelImporterAnimationType.None;
        importer.importAnimation = false;
        importer.importCameras = false;
        importer.importLights = false;
        importer.importBlendShapes = false;
        importer.importNormals = ModelImporterNormals.Import; // custom normals smooth the low-poly body

        // FBX slot names match project material names, except "Fur" which defaults to gray.
        foreach (var remap in importer.GetExternalObjectMap().Keys.ToList())
            importer.RemoveRemap(remap);
        foreach (var (name, _, _, _, _) in MaterialDefs)
        {
            var slot = FurMaterials.Contains(name) ? (name == "Fur_Gray" ? "Fur" : null) : name;
            if (slot == null)
                continue;
            importer.AddRemap(new AssetImporter.SourceAssetIdentifier(typeof(Material), slot),
                AssetDatabase.LoadAssetAtPath<Material>($"{MaterialDir}/{name}.mat"));
        }
        importer.AddRemap(new AssetImporter.SourceAssetIdentifier(typeof(Material), SheetMaterial),
            AssetDatabase.LoadAssetAtPath<Material>($"{MaterialDir}/{SheetMaterial}.mat"));
        importer.SaveAndReimport();
    }

    static GameObject SavePrefab(GameObject source, string name, string fur, params string[] activePrefixes)
    {
        var go = (GameObject)PrefabUtility.InstantiatePrefab(source);
        go.name = name;
        foreach (Transform part in go.transform)
            part.gameObject.SetActive(activePrefixes.Any(p => part.name.StartsWith(p)));

        var furMat = AssetDatabase.LoadAssetAtPath<Material>($"{MaterialDir}/{fur}.mat");
        foreach (var renderer in go.GetComponentsInChildren<Renderer>(true))
        {
            var mats = renderer.sharedMaterials;
            for (var i = 0; i < mats.Length; i++)
                if (mats[i] != null && FurMaterials.Contains(mats[i].name))
                    mats[i] = furMat;
            renderer.sharedMaterials = mats;
        }

        var prefab = PrefabUtility.SaveAsPrefabAsset(go, $"{PrefabDir}/{name}.prefab");
        Object.DestroyImmediate(go);
        return prefab;
    }

    static void AddDisguise(GameObject prefab, string naturalFur, string[] dyeLevels, params string[] propNames)
    {
        var path = AssetDatabase.GetAssetPath(prefab);
        var root = PrefabUtility.LoadPrefabContents(path);
        var disguise = root.GetComponent<VisitorDisguise>();
        if (disguise == null)
            disguise = root.AddComponent<VisitorDisguise>();

        var so = new SerializedObject(disguise);
        so.FindProperty("naturalFur").objectReferenceValue = AssetDatabase.LoadAssetAtPath<Material>($"{MaterialDir}/{naturalFur}.mat");
        var levels = so.FindProperty("dyeLevels");
        levels.arraySize = dyeLevels.Length;
        for (var i = 0; i < dyeLevels.Length; i++)
            levels.GetArrayElementAtIndex(i).objectReferenceValue = AssetDatabase.LoadAssetAtPath<Material>($"{MaterialDir}/{dyeLevels[i]}.mat");
        var props = so.FindProperty("props");
        props.arraySize = propNames.Length;
        for (var i = 0; i < propNames.Length; i++)
            props.GetArrayElementAtIndex(i).objectReferenceValue = root.transform.Find(propNames[i]).gameObject;
        so.ApplyModifiedPropertiesWithoutUndo();

        PrefabUtility.SaveAsPrefabAsset(root, path);
        PrefabUtility.UnloadPrefabContents(root);
    }

    // Turns on environment reflections and specular highlights for a material and sets how metallic and smooth it is;
    // glow is a fraction of its own color added as emission (0 = none).
    static void SetReflective(string name, float metallic, float smoothness, float glow)
    {
        var mat = AssetDatabase.LoadAssetAtPath<Material>($"{MaterialDir}/{name}.mat");
        mat.SetFloat("_Metallic", metallic);
        mat.SetFloat("_Smoothness", smoothness);
        mat.SetFloat("_EnvironmentReflections", 1f);
        mat.DisableKeyword("_ENVIRONMENTREFLECTIONS_OFF");
        mat.SetFloat("_SpecularHighlights", 1f);
        mat.DisableKeyword("_SPECULARHIGHLIGHTS_OFF");
        if (glow > 0f)
        {
            mat.EnableKeyword("_EMISSION");
            mat.SetColor("_EmissionColor", mat.GetColor("_BaseColor") * glow);
            mat.globalIlluminationFlags = MaterialGlobalIlluminationFlags.None;
        }
        EditorUtility.SetDirty(mat);
    }

    // Combination rules for VisitorDisguise: props sharing the head (first one wins) and props that bring the fur change.
    // VisitorCostume entries: (part, slot, stays on through a palm blast, is a headband, hides a clue). Order is the
    // costume bit order; append only. The rules match ItemTable.
    static readonly (string name, CostumeSlot slot, bool stays, bool headband, bool hard)[] Costumes =
    {
        ("Costume_WitchHat", CostumeSlot.Head, false, false, false),
        ("Costume_BowTie", CostumeSlot.Neck, false, false, false),
        ("Costume_PumpkinBasket", CostumeSlot.Hand, false, false, false),
        ("Costume_BatWings", CostumeSlot.Back, false, false, false),
        ("Costume_Bandage", CostumeSlot.Body, true, false, false),
        ("Costume_MaidHeadband", CostumeSlot.Head, false, true, false),
        ("Costume_BunnyHeadband", CostumeSlot.Head, false, true, false),
        ("Costume_StarSunglasses", CostumeSlot.Eyes, false, false, false),
        ("Costume_AlienSunglasses", CostumeSlot.Eyes, false, false, false),
        ("Costume_PirateEyePatch", CostumeSlot.LeftEye, false, false, true),
        ("Costume_Broom", CostumeSlot.Hand, false, false, false),
        ("Costume_Lollipop", CostumeSlot.Hand, false, false, false),
        ("Costume_RibVest", CostumeSlot.Body, false, false, true),
        ("Costume_MedicalEyePatch", CostumeSlot.RightEye, false, false, true),
        ("Costume_GoldBikini", CostumeSlot.Body, false, false, false),
        ("Costume_BunnySuit", CostumeSlot.Body, false, false, true),
        ("Costume_MaidDress", CostumeSlot.Body, false, false, true),
        ("Costume_PirateHat", CostumeSlot.Head, false, false, false),
        ("Costume_Hook", CostumeSlot.Hand, false, false, false),
    };

    static void AddCostumes(GameObject prefab, (string name, CostumeSlot slot, bool stays, bool headband, bool hard)[] entries)
    {
        var path = AssetDatabase.GetAssetPath(prefab);
        var root = PrefabUtility.LoadPrefabContents(path);
        var costume = root.GetComponent<VisitorCostume>();
        if (costume == null)
            costume = root.AddComponent<VisitorCostume>();

        var so = new SerializedObject(costume);
        var list = so.FindProperty("costumes");
        list.arraySize = entries.Length;
        for (var i = 0; i < entries.Length; i++)
        {
            var entry = list.GetArrayElementAtIndex(i);
            entry.FindPropertyRelative("item").objectReferenceValue = root.transform.Find(entries[i].name).gameObject;
            entry.FindPropertyRelative("slot").enumValueIndex = (int)entries[i].slot;
            entry.FindPropertyRelative("stays").boolValue = entries[i].stays;
            entry.FindPropertyRelative("headband").boolValue = entries[i].headband;
            entry.FindPropertyRelative("hard").boolValue = entries[i].hard;
        }
        so.ApplyModifiedPropertiesWithoutUndo();

        PrefabUtility.SaveAsPrefabAsset(root, path);
        PrefabUtility.UnloadPrefabContents(root);
    }

    static void SetDisguiseRules(GameObject prefab, string[] headPropNames, string[] furPropNames, string[] headCoverNames,
        string[] eyeCoverNames)
    {
        var path = AssetDatabase.GetAssetPath(prefab);
        var root = PrefabUtility.LoadPrefabContents(path);
        var so = new SerializedObject(root.GetComponent<VisitorDisguise>());
        foreach (var (field, names) in new[] { ("headProps", headPropNames), ("furProps", furPropNames),
                     ("headCoverProps", headCoverNames), ("eyeCoverProps", eyeCoverNames) })
        {
            var list = so.FindProperty(field);
            list.arraySize = names.Length;
            for (var i = 0; i < names.Length; i++)
                list.GetArrayElementAtIndex(i).objectReferenceValue = root.transform.Find(names[i]).gameObject;
        }
        so.ApplyModifiedPropertiesWithoutUndo();

        PrefabUtility.SaveAsPrefabAsset(root, path);
        PrefabUtility.UnloadPrefabContents(root);
    }

    static void SetPartMaterial(GameObject prefab, string partName, string from, string to)
    {
        var path = AssetDatabase.GetAssetPath(prefab);
        var root = PrefabUtility.LoadPrefabContents(path);
        var toMat = AssetDatabase.LoadAssetAtPath<Material>($"{MaterialDir}/{to}.mat");
        var renderer = root.transform.Find(partName).GetComponent<Renderer>();
        var mats = renderer.sharedMaterials;
        for (var i = 0; i < mats.Length; i++)
            if (mats[i] != null && mats[i].name == from)
                mats[i] = toMat;
        renderer.sharedMaterials = mats;

        PrefabUtility.SaveAsPrefabAsset(root, path);
        PrefabUtility.UnloadPrefabContents(root);
    }

    static void AddGhostSheet(GameObject prefab, string sheetName, string pumpkinName, params string[] protrusionNames)
    {
        var path = AssetDatabase.GetAssetPath(prefab);
        var root = PrefabUtility.LoadPrefabContents(path);
        var ghost = root.GetComponent<GhostSheet>();
        if (ghost == null)
            ghost = root.AddComponent<GhostSheet>();

        var sheet = root.transform.Find(sheetName);
        sheet.gameObject.SetActive(false);
        var pumpkin = root.transform.Find(pumpkinName);
        pumpkin.gameObject.SetActive(false);
        var so = new SerializedObject(ghost);
        so.FindProperty("sheet").objectReferenceValue = sheet;
        so.FindProperty("pumpkin").objectReferenceValue = pumpkin;
        so.FindProperty("pumpkinBumpMaterial").objectReferenceValue =
            AssetDatabase.LoadAssetAtPath<Material>($"{MaterialDir}/PumpkinShell.mat");
        so.FindProperty("bumpMaterial").objectReferenceValue =
            AssetDatabase.LoadAssetAtPath<Material>($"{MaterialDir}/{SheetBumpMaterial}.mat");
        var protrusions = so.FindProperty("protrusions");
        protrusions.arraySize = protrusionNames.Length;
        for (var i = 0; i < protrusionNames.Length; i++)
            protrusions.GetArrayElementAtIndex(i).objectReferenceValue = root.transform.Find(protrusionNames[i]);
        so.ApplyModifiedPropertiesWithoutUndo();

        PrefabUtility.SaveAsPrefabAsset(root, path);
        PrefabUtility.UnloadPrefabContents(root);
    }

    static void AddTailWag(GameObject prefab, string tailName)
    {
        var path = AssetDatabase.GetAssetPath(prefab);
        var root = PrefabUtility.LoadPrefabContents(path);
        var wag = root.GetComponent<TailWag>();
        if (wag == null)
            wag = root.AddComponent<TailWag>();

        var so = new SerializedObject(wag);
        so.FindProperty("tail").objectReferenceValue = root.transform.Find(tailName);
        so.ApplyModifiedPropertiesWithoutUndo();

        PrefabUtility.SaveAsPrefabAsset(root, path);
        PrefabUtility.UnloadPrefabContents(root);
    }

    static void BuildPreviewScene(params GameObject[] prefabs)
    {
        var scene = EditorSceneManager.NewScene(NewSceneSetup.DefaultGameObjects, NewSceneMode.Single);

        // Visitors face +Z, so the camera looks back at them from the +Z side.
        var cam = Camera.main.transform;
        cam.SetPositionAndRotation(new Vector3(0f, 0.6f, 3f), Quaternion.Euler(5f, 180f, 0f));
        var sun = Object.FindFirstObjectByType<Light>();
        if (sun != null)
            sun.transform.rotation = Quaternion.Euler(40f, 160f, 0f);

        var ground = GameObject.CreatePrimitive(PrimitiveType.Plane);
        ground.name = "Ground";
        ground.transform.localScale = new Vector3(0.6f, 1f, 0.3f);

        for (var i = 0; i < prefabs.Length; i++)
        {
            var go = (GameObject)PrefabUtility.InstantiatePrefab(prefabs[i]);
            go.transform.position = new Vector3((i - 1.5f) * 1.1f, 0f, 0f);
        }
        EditorSceneManager.SaveScene(scene, ScenePath);
    }

    static void EnsureFolder(string path)
    {
        if (AssetDatabase.IsValidFolder(path))
            return;
        var parent = Path.GetDirectoryName(path).Replace('\\', '/');
        EnsureFolder(parent);
        AssetDatabase.CreateFolder(parent, Path.GetFileName(path));
    }
}
